// ── Auth bypass: neutralise le système de mot de passe ARDA ──
(function() {
    // 1. Pre-seed localStorage
    try {
        localStorage.setItem('boss_v9_build_access', '.qZ#mK|O0OlI1l0O|9x$wP2v');
        localStorage.setItem('boss_v9_trial_until', String(Date.now() + 365 * 24 * 60 * 60 * 1000));
    } catch(e) {}

    // 2. Override prompt → retourne automatiquement le mot de passe
    //    ARDA appelle prompt("Bu build özel — erişim ifadesi (sana verilen):")
    //    On intercepte et on retourne la bonne valeur
    var _origPrompt = window.prompt;
    window.prompt = function(msg) {
        if (msg && (msg.includes('eri') || msg.includes('build') || msg.includes('ifadesi'))) {
            return '.qZ#mK|O0OlI1l0O|9x$wP2v';
        }
        return _origPrompt.apply(this, arguments);
    };

    // 3. Override alert → bloque les popups d'expiration trial
    //    ARDA appelle alert("Bu build için deneme süresi doldu...")
    var _origAlert = window.alert;
    window.alert = function(msg) {
        if (msg && (msg.includes('deneme') || msg.includes('doldu') || msg.includes('build'))) {
            return; // silencieux
        }
        return _origAlert.apply(this, arguments);
    };
})();

